const $=id=>document.getElementById(id);
let state={spec:{operation:'matrix_multiply',size:8,precision:'int8',target:'kv260',frequency_mhz:100,max_dsps:16,max_lanes:4,objective:'minimize_latency'},result:null,boardResult:null,boardAvailable:false,boardRecorded:false,vivadoImports:{},configurationAccepted:false,busy:false,simulator:false,ai:false,draft:null,asicSynthesis:false,synthesis:null,synthesisPrompt:undefined,runs:[],exploration:0};
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notice(message,error=false){$('notice').hidden=false;$('notice').className='notice'+(error?' error':'');$('notice').textContent=message;}
async function api(path,body){const response=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Request failed');return result;}
function sameObject(a,b){return JSON.stringify(a,Object.keys(a).sort())===JSON.stringify(b,Object.keys(b).sort());}
function isGenerated(report){return report.evidence==='ai_generated_rtl'||report.source_origin==='ai_generated_rtl';}
function isAcceptedSimulation(report){return Boolean(report?.correct&&['rtl_simulation','ai_generated_rtl'].includes(report.evidence)&&report.id);}
function setStage(name,status,kind='waiting'){const stage=document.querySelector(`[data-stage="${name}"]`);if(!stage)return;stage.className=kind;const label=stage.querySelector('small');if(label)label.textContent=status;}
function updatePipeline(){const accepted=isAcceptedSimulation(state.result),current=accepted&&!reportIsStale(state.result),boardRecorded=state.boardResult?.evidence==='board_measured',board=boardRecorded&&current&&state.boardResult.parent_run_id===state.result.id;setStage('configure',state.configurationAccepted?'Reviewed':'Ready',state.configurationAccepted?'passed':'selected');setStage('select',current?'RTL selected':state.configurationAccepted?'Options ready':'Waiting',current?'passed':state.configurationAccepted?'selected':'waiting');setStage('verify',current?'RTL simulated':accepted?'Earlier result is stale':'Not yet verified',current?'passed':'waiting');setStage('implement',board?'Recorded artifact':'Not yet verified',board?'passed':'waiting');setStage('board',board?'Board measured':boardRecorded?'Recorded for another configuration':state.boardRecorded?'Recorded runs in history':state.boardAvailable?'Runner available':'Awaiting board evidence',board?'passed':state.boardRecorded||state.boardAvailable?'selected':'waiting');setStage('export',accepted?current?'Ready':'Earlier report ready':'Waiting',accepted?'selected':'waiting');}
function updateEvidenceControls(){const accepted=isAcceptedSimulation(state.result),fpgaAccepted=accepted&&state.result.spec?.target==='kv260';$('export').disabled=state.busy||!accepted;$('handoff').disabled=state.busy||!fpgaAccepted;$('board-result-file').disabled=state.busy||!fpgaAccepted;$('import-board-result').disabled=state.busy||!fpgaAccepted||!$('board-result-file').files?.length;updatePipeline();}
function reportIsStale(report,prompt=report.prompt){return !sameObject(report.spec,readSpec())||(isGenerated(report)&&prompt!==$('prompt').value);}
function updateEvidenceState(){if(state.synthesis&&$('stale-synthesis'))$('stale-synthesis').hidden=!reportIsStale(state.synthesis,state.synthesisPrompt);if(state.result&&$('stale-result'))$('stale-result').hidden=!reportIsStale(state.result);if(state.boardResult&&$('stale-board-result'))$('stale-board-result').hidden=Boolean(state.result)&&state.boardResult.parent_run_id===state.result.id&&!reportIsStale(state.result);updateEvidenceControls();}
function updateGenerateRtl(){const spec=readSpec(),lanes=spec.objective==='minimize_lanes'?1:spec.max_lanes;const missing=[];if(!state.ai)missing.push('configured Groq AI');if(!state.simulator)missing.push('Icarus Verilog');if(spec.target==='asic'&&!state.asicSynthesis)missing.push('Yosys synthesis');const empty=!$('prompt').value.trim();$('generate-rtl').disabled=state.busy||missing.length>0||empty;$('generate-rtl').title=missing.length?'Requires '+missing.join(', '):empty?'Describe a workload to generate RTL':'Generate new RTL and accept it only after verification';$('generate-rtl-help').textContent=`Uses your reviewed specification: ${spec.size} × ${spec.size} INT8, ${lanes} requested lane${lanes>1?'s':''}. ${spec.objective==='minimize_lanes'?'The lane objective selects 1 lane.':'The latency objective selects the lane limit.'} ${spec.target==='asic'?'Runs RTL simulation, integer-oracle checks, and generic synthesis with netlist verification.':'Runs RTL simulation and integer-oracle checks.'}${missing.length?' Requires '+missing.join(', ')+'.':''}`;}

function updateCompare(){const allowed=readSpec().max_lanes>=2;$('compare').disabled=state.busy||!state.simulator||!allowed;$('compare-help').textContent=!allowed?'Set the parallel lane limit to 2 or 4 to compare architectures.':!state.simulator?'RTL simulation requires Icarus Verilog on this server.':'Runs 1 lane and the selected parallel lane count on identical seeded inputs; no hardware required.';}
function targetLabel(target){return target==='asic'?'Custom ASIC':'AMD Kria KV260';}
function updateTarget(){updateGenerateRtl();$('vivado-import').hidden=state.spec.target==='asic';if($('apply-draft'))$('apply-draft').disabled=state.busy||!state.draft?.supported||state.draft.spec.target!==state.spec.target;if($('draft-target-note'))$('draft-target-note').hidden=!state.draft?.supported||state.draft.spec.target===state.spec.target;const asic=state.spec.target==='asic';document.querySelectorAll('[data-target]').forEach(b=>{b.classList.toggle('active',b.dataset.target===state.spec.target);b.setAttribute('aria-pressed',String(b.dataset.target===state.spec.target));});$('target-name').textContent=targetLabel(state.spec.target);$('target-state').textContent=asic?'Generic logic · no physical chip':state.boardRecorded?'Recorded KV260 runs available':state.boardAvailable?'Board runner available':'Board runner status unknown';$('board-connection-label').textContent=state.boardRecorded?'RECORDED BOARD RUNS':state.boardAvailable?'RUNNER AVAILABLE':'LIVE BOARD STATUS UNKNOWN';$('target-art').textContent=asic?'CUSTOM ASIC · GENERIC LOGIC':'K26 · PROGRAMMABLE LOGIC';$('spec-target').textContent='Signed INT8 → INT32 · '+targetLabel(state.spec.target);$('dsp-field').hidden=asic;$('board-evidence').hidden=asic;$('asic-stage').hidden=!asic;$('architecture-note').textContent=asic?'Cycle projections describe this RTL schedule. Generic synthesis does not establish silicon area, power, or achieved clock frequency.':'Cycle projections describe this RTL schedule. Timing closure and DSP, LUT, and BRAM usage need Vivado reports.';$('synthesis-status').textContent=state.synthesis?'Report available · inspect below':state.asicSynthesis?'Yosys available · ready to run':'Yosys unavailable on this server';$('prompt').placeholder=asic?'Describe an INT8 matrix multiplication engine for a custom ASIC. Review the generic design before technology mapping.':'Describe an INT8 matrix multiplication accelerator for a Kria KV260.';updatePipeline();}
document.querySelectorAll('[data-target]').forEach(b=>b.onclick=async()=>{if(state.busy)return;state.spec=readSpec();state.spec.target=b.dataset.target;updateTarget();await explore();});
const supportedPresets={'8-1':{size:8,max_lanes:1,objective:'minimize_lanes'},'8-2':{size:8,max_lanes:2,objective:'minimize_latency'},'8-4':{size:8,max_lanes:4,objective:'minimize_latency'},'16-1':{size:16,max_lanes:1,objective:'minimize_lanes'},'16-2':{size:16,max_lanes:2,objective:'minimize_latency'},'16-4':{size:16,max_lanes:4,objective:'minimize_latency'}};
function updatePresetSelection(){const spec=readSpec();document.querySelectorAll('[data-preset]').forEach(button=>{const preset=supportedPresets[button.dataset.preset],active=spec.size===preset.size&&spec.max_lanes===preset.max_lanes&&spec.objective===preset.objective;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});}
document.querySelectorAll('[data-preset]').forEach(button=>button.onclick=async()=>{if(state.busy)return;fillSpec({...readSpec(),...supportedPresets[button.dataset.preset]});await explore();notice('Supported configuration loaded. Run RTL simulation to verify this parameter set.');});
function readSpec(){return {...state.spec,...Object.fromEntries(['size','frequency_mhz','max_dsps','max_lanes'].map(k=>[k,Number($(k).value)])),precision:$('precision').value,objective:$('objective').value};}
function fillSpec(spec,provenance={}){state.spec=spec;updateTarget();for(const key of ['size','precision','frequency_mhz','max_dsps','max_lanes','objective'])$(key).value=spec[key];document.querySelectorAll('[data-source]').forEach(el=>{el.textContent=provenance[el.dataset.source]?'Source: '+provenance[el.dataset.source]:'Reviewed configuration';});updateGenerateRtl();}
function vivadoFor(candidate){return state.spec.target==='kv260'?state.vivadoImports[`${state.spec.size}:${candidate.lanes}`]||null:null;}
async function explore(event){if(event)event.preventDefault();if(!$('spec-form').reportValidity())return;updatePresetSelection();updateEvidenceState();updateCompare();updateGenerateRtl();const request=++state.exploration;try{state.spec=readSpec();const data=await api('/api/explore',{spec:state.spec});if(request!==state.exploration)return;state.configurationAccepted=true;updatePipeline();$('candidate-grid').innerHTML=data.candidates.map(c=>`<article class="candidate ${c.id===data.provisional?'recommended':''} ${!c.within_lane_limit?'excluded':''}"><div class="candidate-head"><h3>${c.lanes===1?'Sequential MAC':'Parallel MAC array'}</h3><span class="tag">${!c.within_lane_limit?'OVER LANE LIMIT':c.id===data.provisional?'PROVISIONAL SELECTION':'BASELINE'}</span></div><p>${c.lanes===1?'One arithmetic lane executes the schedule sequentially.':`${c.lanes} arithmetic lanes process ${c.lanes} output columns in parallel, using ${c.lanes} times the baseline MAC capacity.`}</p><div class="lane-diagram" aria-label="${c.lanes} arithmetic lanes"><span class="lane-port">A,B</span><span class="lane-link"></span>${'<span class="lane">MAC</span>'.repeat(c.lanes)}<span class="lane-link"></span><span class="lane-port">C</span></div><div class="metrics"><div class="metric"><small>PROJECTED KERNEL TIME · NOT MEASURED</small><strong>${c.projected_us.toFixed(2)} <em>µs</em></strong></div><div class="metric"><small>MODEL CYCLES</small><strong>${c.cycles.toLocaleString()}</strong></div><div class="metric"><small>${state.spec.target==='asic'?'MAC LANES':vivadoFor(c)?vivadoFor(c).evidence==='user_imported_vivado_implementation'?'IMPORTED DSPs · ROUTED':'IMPORTED DSPs · OOC':'DSP COUNT · PENDING'}</small><strong>${state.spec.target==='asic'?c.lanes.toLocaleString():vivadoFor(c)?.resources.dsp??'—'}</strong></div></div><div class="candidate-footer"><span>ANALYTICAL · ${state.spec.frequency_mhz} MHz assumed</span><button data-run="${c.lanes}" ${!c.within_lane_limit||state.busy||!state.simulator?'disabled':''}>Run RTL simulation ↗</button>${state.spec.target==='asic'?`<button data-synthesize="${c.lanes}" ${!c.within_lane_limit||state.busy||!state.asicSynthesis?'disabled':''}>Synthesize generic logic ↗</button>`:''}</div></article>`).join('');$('constraint-text').textContent=`${data.warning} ${state.spec.target==='asic'?'Generic synthesis reports logic cells; silicon metrics await implementation.':`Current requested budget: ${state.spec.max_dsps} DSPs.`} The provisional selection follows the ${state.spec.objective==='minimize_latency'?'lower projected cycle count':'lower lane count'} objective only.`;document.querySelectorAll('[data-run]').forEach(b=>b.onclick=()=>run(Number(b.dataset.run)));document.querySelectorAll('[data-synthesize]').forEach(b=>b.onclick=()=>synthesize(Number(b.dataset.synthesize)));}catch(e){if(request===state.exploration){state.configurationAccepted=false;updatePipeline();}notice(e.message,true);}}
function setBusy(busy){state.busy=busy;document.querySelectorAll('.builder button,.builder input,.builder select,.builder textarea,[data-build],[data-run],[data-target],[data-synthesize],[data-preset]').forEach(el=>el.disabled=busy);$('generate').disabled=busy||!state.ai;if($('apply-draft'))$('apply-draft').disabled=busy||!state.draft?.supported||state.draft.spec.target!==state.spec.target;document.querySelector('.builder').setAttribute('aria-busy',String(busy));$('sample').disabled=busy;updateCompare();updateGenerateRtl();updateEvidenceControls();}
function comparable(a,b){return a.correct&&b.correct&&['rtl_simulation','ai_generated_rtl'].includes(a.evidence)&&b.evidence===a.evidence&&a.input_sha256&&a.input_sha256===b.input_sha256&&a.output_sha256===b.output_sha256&&a.simulator===b.simulator&&sameObject(a.spec,b.spec)&&a.source_sha256&&Object.keys(a.source_sha256).length>0&&sameObject(a.source_sha256,b.source_sha256);}
function comparison(result){const other=state.runs.find(r=>r.lanes!==result.lanes&&comparable(r,result));if(!other)return `<p class="comparison-hint">${isGenerated(result)?'Generated RTL comparisons require the same generated source, inputs, outputs, specification, and simulator. Checked-in architecture projections do not describe this generated schedule.':'Run another architecture with the same specification to compare verified simulation cycles.'}</p>`;const slower=result.lanes<other.lanes?result:other,faster=result.lanes>other.lanes?result:other;return `<div class="comparison"><div><span class="eyebrow">MATCHED ${isGenerated(result)?'AI RTL ':''}SIMULATION CAPACITY COMPARISON</span><h3>${(slower.cycles/faster.cycles).toFixed(2)}× fewer simulated compute cycles</h3><p>${slower.lanes} lane${slower.lanes>1?'s':''}: ${slower.cycles.toLocaleString()} cycles → ${faster.lanes} lanes: ${faster.cycles.toLocaleString()} cycles</p></div><p>${isGenerated(result)?'The wider configuration requests more arithmetic capacity. Observed cycle counts belong only to this verified generated source.':'The wider configuration spends more arithmetic capacity to finish this schedule in fewer cycles.'} Loading and host communication are excluded. This is not a physical speedup measurement.</p></div>`;}
function renderResult(result){state.result=result;const r=result,generated=isGenerated(r);$('result').className='result-filled';$('result').innerHTML=`<p id="stale-result" class="notice" hidden>This report belongs to an earlier ${generated?'specification or workload prompt':'specification'}. Run the current configuration to refresh the evidence. Export and handoff still refer to this displayed report.</p><div class="result-top"><div><h3>Correct output. Reproducible run.</h3><p>${r.spec.size} × ${r.spec.size} INT8 · ${r.lanes} lane${r.lanes>1?'s':''} · ${targetLabel(r.spec.target)} · Seed ${r.seed}</p></div><span class="tag">${generated?'AI-GENERATED RTL':'CHECKED-IN RTL SIMULATION'} · NOT HARDWARE MEASURED</span></div>${generated?'<p class="evidence-origin">AI-generated RTL, verified by simulation against an integer oracle</p>':''}<div class="metrics"><div class="metric"><small>SIMULATED CYCLES</small><strong>${r.cycles.toLocaleString()}</strong></div><div class="metric"><small>PROJECTED AT ASSUMED TARGET CLOCK · NOT MEASURED</small><strong>${r.projected_us.toFixed(2)} <em>µs</em></strong></div><div class="metric"><small>OUTPUTS VERIFIED</small><strong>${r.outputs.length} <em>/ ${r.outputs.length}</em></strong></div></div><p class="subtle">Kernel cycles exclude operand loading and host transfers. ${r.lanes>1?`${r.lanes} lanes use ${r.lanes} times the one-lane arithmetic capacity; resource mapping remains unknown.`:'The one-lane result is the lower-capacity schedule.'}</p>${comparison(r)}<details><summary>Inspect provenance, outputs, and limitations</summary><ul>${r.limitations.map(t=>`<li>${escapeHtml(t)}</li>`).join('')}</ul><pre>${escapeHtml(JSON.stringify(r,null,2))}</pre></details>`;updateEvidenceState();}
function renderBoardResult(report){if(report?.evidence!=='board_measured')throw new Error('The server did not return board_measured evidence.');state.boardResult=report;state.boardRecorded=true;updateTarget();const build=report.build||{},board=report.board||{},run=report.run||{},parameters=build.parameters||{},connected='PARENT RUN VERIFIED',outputs=Array.isArray(run.outputs)?run.outputs.length:null,clock=Number(build.configured_clock_hz);$('board-result').className='result-filled board-result-filled';$('board-result').innerHTML=`<p id="stale-board-result" class="notice" hidden>This recorded board measurement belongs to parent run ${escapeHtml(report.parent_run_id||'unknown')}, not the currently selected simulation.</p><div class="result-top"><div><h3>Recorded KV260 board measurement.</h3><p>Immutable child evidence · parent ${escapeHtml(report.parent_run_id||'unknown')}</p></div><span class="tag">RECORDED BOARD MEASUREMENT · ${connected}</span></div><dl class="board-facts"><div><dt>Artifact / bitstream SHA-256</dt><dd>${escapeHtml(build.bitstream_sha256||'Unknown')}</dd></div><div><dt>Target part · configuration</dt><dd>${escapeHtml(build.target_part||'Unknown')} · N=${escapeHtml(parameters.N??'Unknown')} · LANES=${escapeHtml(parameters.LANES??'Unknown')}</dd></div><div><dt>Board identity</dt><dd>${escapeHtml([board.sku,board.board_revision].filter(Boolean).join(' · ')||'Unknown')}</dd></div><div><dt>Board image</dt><dd>${escapeHtml(board.image_identity||'Unknown')}</dd></div><div><dt>Configured clock</dt><dd>${Number.isFinite(clock)?`${(clock/1000000).toLocaleString()} MHz`:'Unknown'}</dd></div><div><dt>Physical cycle count</dt><dd>${escapeHtml(run.cycles??report.cycles??'Unknown')}</dd></div><div><dt>Output check</dt><dd>${report.correct===true?`All ${outputs??''} outputs matched the server oracle`.replace('All  outputs','All outputs'):'Not accepted as a complete oracle match'}</dd></div><div><dt>Recorded timestamp</dt><dd>${escapeHtml(report.recorded_at||report.created_at||'Unknown')}</dd></div>${run.host_elapsed_ns!=null?`<div><dt>Host elapsed</dt><dd>${escapeHtml(run.host_elapsed_ns)} ns</dd></div>`:''}${run.programming_elapsed_ns!=null?`<div><dt>Programming elapsed</dt><dd>${escapeHtml(run.programming_elapsed_ns)} ns</dd></div>`:''}</dl><details><summary>Inspect board provenance</summary><pre>${escapeHtml(JSON.stringify(report,null,2))}</pre></details>`;updateEvidenceState();}
async function importBoardResult(payload){if(state.busy||!isAcceptedSimulation(state.result)||state.result.spec?.target!=='kv260')return;const parent=state.result;try{if(payload===undefined){const file=$('board-result-file').files?.[0];if(!file)throw new Error('Choose a board-result JSON file first.');payload=JSON.parse(await file.text());}setBusy(true);$('board-import-status').textContent=`Validating signed board result against simulation run ${parent.id}…`;notice(`Validating board result against simulation run ${parent.id}…`);const report=await api(`/api/runs/${encodeURIComponent(parent.id)}/board-result`,payload);if(report.evidence!=='board_measured'||report.correct!==true)throw new Error('The server did not return accepted board_measured evidence.');renderBoardResult(report);state.runs=[report,...state.runs];$('board-import-status').textContent='Accepted and recorded: signed board measurement matched this simulation.';notice('Recorded board measurement accepted. It remains separate from the parent RTL simulation.');$('board-evidence').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return report;}catch(e){$('board-import-status').textContent='Board result rejected: '+e.message;notice('Board result rejected: '+e.message,true);}finally{setBusy(false);}}
function historyLabel(report){if(report.evidence==='board_measured')return 'Recorded board measurement';return report.evidence==='generic_synthesis'?(isGenerated(report)?'Generic synthesis · AI-generated RTL':'Generic synthesis'):isGenerated(report)?'AI-generated RTL'+(report.synthesis_verified?' · generic synthesis verified':''):'Checked-in RTL simulation'+(report.synthesis_verified?' · generic synthesis verified':'');}
async function history(){const runs=await api('/api/runs');state.runs=runs;state.boardRecorded=state.boardRecorded||runs.some(r=>r.evidence==='board_measured');updateTarget();if(state.result)renderResult(state.result);$('history').innerHTML=runs.slice(0,5).map(r=>`<div class="history-row"><span>✓ ${historyLabel(r)}</span><span>${targetLabel(r.spec?.target||'kv260')} · ${r.spec?.size||r.build?.parameters?.N||'—'}×${r.spec?.size||r.build?.parameters?.N||'—'} · ${r.lanes||r.build?.parameters?.LANES||'—'} lane${(r.lanes||r.build?.parameters?.LANES)!==1?'s':''}</span><span>${r.evidence==='generic_synthesis'?`${r.cell_count} generic cells`:r.evidence==='board_measured'?`${r.run?.cycles??r.cycles??'—'} physical cycles`:`${r.cycles} cycles`}</span><span>${escapeHtml(new Date(r.recorded_at||r.created_at).toLocaleTimeString())}</span><button data-view="${r.id}">Inspect ↗</button></div>`).join('');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=async()=>{if(state.busy)return;try{const report=await api('/api/runs/'+b.dataset.view);if(state.busy)return;if(report.evidence==='board_measured'){state.spec=readSpec();state.spec.target='kv260';updateTarget();await explore();renderBoardResult(report);$('board-evidence').scrollIntoView({behavior:'smooth'});return;}if(report.evidence==='generic_synthesis'||report.synthesis){state.spec=readSpec();state.spec.target='asic';updateTarget();await explore();}if(report.evidence==='generic_synthesis'){renderSynthesis(report);$('asic-stage').scrollIntoView({behavior:'smooth'});}else{renderResult(report);if(report.synthesis)renderSynthesis(report.synthesis,report.prompt);$('evidence').scrollIntoView({behavior:'smooth'});}}catch(e){notice(e.message,true);}});}
async function generateRtl(){
 updateGenerateRtl();if($('generate-rtl').disabled||!$('spec-form').reportValidity())return;
 const spec=readSpec(),prompt=$('prompt').value,button=$('generate-rtl');let accepted=false;
 setBusy(true);button.textContent=spec.target==='asic'?'Generating, verifying & synthesizing…':'Generating & verifying…';
 notice(spec.target==='asic'?'Generating new RTL, checking the source, simulating against the integer oracle, then synthesizing and verifying the netlist…':'Generating new RTL, checking the source, and simulating against the integer oracle…');
 try{
  const result=await api('/api/generate-rtl',{spec,prompt});
  if(result.evidence!=='ai_generated_rtl'||result.correct!==true||(spec.target==='asic'&&(result.synthesis?.evidence!=='generic_synthesis'||result.synthesis?.source_origin!=='ai_generated_rtl'||result.synthesis?.correct!==true)))throw new Error('The server did not return a fully verified generated design. No report displayed.');
  state.runs=[result,...state.runs];renderResult(result);if(result.synthesis)renderSynthesis(result.synthesis,result.prompt);accepted=true;
  await history();
  notice('AI-generated RTL, verified by simulation against an integer oracle.'+(result.synthesis?' Generic synthesis and netlist verification also passed.':'')+' Physical resources and hardware performance remain unverified.');
  $('evidence').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
 }catch(e){notice(accepted?'Generated RTL verification passed. The accepted report remains displayed, but history could not be refreshed: '+e.message:'RTL generation rejected: '+e.message+((state.result||state.synthesis)?' The previously verified report remains displayed.':''),true);}
 finally{setBusy(false);button.innerHTML='Generate &amp; verify RTL <span>↗</span>';await explore();}
}
$('generate-rtl').onclick=generateRtl;
async function run(lanes){return runArchitectures([lanes]);}
async function runArchitectures(lanes){
 if(state.busy||!$('spec-form').reportValidity())return;
 const spec=readSpec();if(lanes.some(l=>l>spec.max_lanes)){notice('Increase the lane limit before running this architecture.',true);return;}
 let completed=0;setBusy(true);await explore();
 try{for(const lane of lanes){notice(`Experiment ${completed+1} of ${lanes.length}: compiling ${lane}-lane RTL, running seeded inputs, and checking every output…`);const result=await api('/api/simulate',{spec,lanes:lane,seed:42});completed++;state.runs=[result,...state.runs];renderResult(result);}
 await history();notice(lanes.length>1?'Both RTL simulations passed. The comparison uses matching inputs and source hashes. Physical timing and resources remain unverified.':'RTL simulation passed. Resource usage and physical hardware performance remain unverified.');$('evidence').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
 }catch(e){notice((completed?`${completed} simulation completed; the next step failed. The completed report remains available. `:'')+e.message,true);}finally{setBusy(false);await explore();}
}
$('compare').onclick=()=>runArchitectures([1,readSpec().max_lanes]);
$('sample').onclick=async()=>{if(state.busy)return;const spec={operation:'matrix_multiply',size:8,precision:'int8',target:state.spec.target,frequency_mhz:100,max_dsps:16,max_lanes:4,objective:'minimize_latency'};fillSpec(spec,Object.fromEntries(Object.keys(spec).map(k=>[k,'built-in sample (not AI generated)'])));await explore();notice('Loaded the built-in 8 × 8 INT8 example. Review its assumptions, then run both architectures to collect actual simulation evidence.');$('architectures').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});};
$('spec-form').onsubmit=explore;
for(const key of ['size','frequency_mhz','max_dsps','max_lanes','objective'])$(key).oninput=()=>{state.configurationAccepted=false;updateEvidenceState();updateCompare();updateGenerateRtl();updatePipeline();};
for(const key of ['size','frequency_mhz','max_dsps','max_lanes','objective'])$(key).onchange=()=>{const badge=document.querySelector(`[data-source="${key}"]`);if(badge)badge.textContent='Source: user';explore();};
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-mode]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-pressed',String(t===b));});const existing=b.dataset.mode==='existing';$('prompt-panel').hidden=existing;$('existing-panel').hidden=!existing;if(existing)$('spec-json').value=JSON.stringify(readSpec(),null,2);else $('prompt').placeholder=b.dataset.mode==='engineer'?'Design an 8×8 INT8 matrix multiplier, at 100 MHz, with no more than 4 lanes.':'Describe the compute workload you want to explore…';});
$('prompt').oninput=()=>{updateEvidenceState();updateGenerateRtl();};
document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{$('prompt').value=b.dataset.example==='fast'?`Design an 8×8 INT8 matrix multiplication accelerator for ${targetLabel(state.spec.target)}. Minimize latency with up to 4 parallel lanes ${state.spec.target==='asic'?'at 100 MHz assumed clock.':'and a 16 DSP budget at 100 MHz.'}`:`Build an 8×8 INT8 matrix multiplication accelerator for ${targetLabel(state.spec.target)} with one arithmetic lane. Minimize the number of lanes.`;$('prompt').oninput();});
$('import').onclick=async()=>{if(state.busy)return;setBusy(true);try{const data=await api('/api/explore',{spec:JSON.parse($('spec-json').value)});fillSpec(data.spec);await explore();notice('Configuration imported and validated. Hardware feasibility still needs implementation reports.');}catch(e){notice(e.message,true);}finally{setBusy(false);await explore();}};
function renderDraft(draft){state.draft=draft;const supported=draft.supported&&draft.spec;$('ai-draft').hidden=false;$('ai-draft').innerHTML=`<div class="eyebrow">AI DRAFT · REVIEW REQUIRED</div><h3 id="draft-heading">${supported?'Review the proposed specification':'Workload not supported'}</h3><p>${escapeHtml(draft.explanation||'Review all assumptions before applying.')}</p>${supported?`<p class="draft-target">Proposed target: ${escapeHtml(targetLabel(draft.spec.target))}</p><table class="cell-table"><thead><tr><th scope="col">Field</th><th scope="col">Proposed value / source</th></tr></thead><tbody>${Object.entries(draft.spec).map(([key,value])=>`<tr><td>${escapeHtml(key.replaceAll('_',' '))}</td><td>${escapeHtml(value)}<small>${escapeHtml(draft.provenance?.[key]||'No field provenance supplied')}</small></td></tr>`).join('')}</tbody></table>`:''}<div class="draft-questions"><strong>Needs your review</strong>${draft.unresolved?.length?`<ul>${draft.unresolved.map(item=>`<li>${escapeHtml(item)}</li>`).join('')}</ul>`:'<p>No unresolved questions were reported. Check every proposed value and assumption.</p>'}</div>${supported?'<p id="draft-target-note" class="notice" hidden>The selected target changed. Switch back to the proposed target or generate a fresh draft before applying.</p><button id="apply-draft" class="button dark">Apply reviewed specification →</button>':''}<p class="subtle">This draft has not changed your active specification. AI suggestions are not hardware measurements.</p>`;if(supported)$('apply-draft').onclick=async()=>{if(state.busy||state.draft.spec.target!==state.spec.target)return;setBusy(true);try{const checked=await api('/api/explore',{spec:state.draft.spec});fillSpec(checked.spec,state.draft.provenance);await explore();$('ai-draft').hidden=true;state.draft=null;notice('Reviewed AI specification applied. You can edit the fields before running an experiment.');}catch(e){notice(e.message,true);}finally{setBusy(false);await explore();}};updateTarget();}
$('generate').onclick=async()=>{if(state.busy||!state.ai)return;const b=$('generate');setBusy(true);b.textContent='Generating draft…';state.draft=null;$('ai-draft').hidden=true;try{const draft=await api('/api/spec',{prompt:$('prompt').value,target:state.spec.target});renderDraft(draft);notice(draft.supported?'AI draft ready. Review its assumptions and apply it explicitly to update your specification.':'This workload is unsupported. Your active specification has not changed.',!draft.supported);}catch(e){notice(e.message,true);}finally{setBusy(false);b.innerHTML='Generate specification <span>↗</span>';}};
$('export').onclick=()=>{if(isAcceptedSimulation(state.result))downloadReport(state.result,`siliconos-${state.result.id}.json`);};
$('handoff').onclick=()=>{if(!isAcceptedSimulation(state.result)||state.result.spec?.target!=='kv260')return;const a=document.createElement('a');a.href=`/api/runs/${encodeURIComponent(state.result.id)}/handoff.zip`;a.download=`siliconos-${state.result.id}-handoff.zip`;a.click();};
$('board-result-file').onchange=()=>{updateEvidenceControls();$('board-import-status').textContent=$('board-result-file').files?.length?'File selected. Click Validate & import board result to check it against the selected simulation.':'Choose a signed board-result JSON from the physical KV260 runner.';};
$('import-board-result').onclick=()=>importBoardResult();
(async()=>{try{const status=await api('/api/status');state.simulator=status.simulator;state.ai=status.ai;state.asicSynthesis=Boolean(status.asic_synthesis);state.boardAvailable=Boolean(status.board);state.boardRecorded=Boolean(status.board_recorded);updateTarget();$('generate').disabled=!state.ai;$('generate').title=state.ai?'Generate an editable specification using the configured AI provider':'An API key must be configured on the server. Use the editable specification or import JSON.';const details=status.ai_details||{};const provider=details.provider||'AI provider',model=details.model||'model not specified';$('ai-status').textContent=status.ai?`${provider} · ${model} configured (connection not yet validated)`: `${provider} not configured. ${details.missing?.length?'Set '+details.missing.join(', ')+' on the server and restart.':'Configure provider credentials on the server and restart.'} Use the no-AI sample meanwhile.`;if(!status.simulator)notice('Icarus Verilog is unavailable on this host. Architecture estimates remain available.',true);await explore();await history();}catch(e){notice('Backend unavailable: '+e.message,true);}})();

$('pilot-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');button.disabled=true;const data=Object.fromEntries(new FormData(form));data.consent=form.elements.consent.checked;try{await api('/api/pilot',data);$('pilot-status').textContent='Saved on this demo server. Thank you for sharing your workflow.';form.reset();}catch(e){$('pilot-status').textContent=e.message;}finally{button.disabled=false;}};

function downloadReport(report,name){const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function genericCellBreakdown(counts){const entries=Object.entries(counts);const registers=entries.reduce((total,[type,count])=>total+(/^\$_/.test(type)&&/(?:DFF|LATCH)/.test(type)?Number(count):0),0);const total=entries.reduce((sum,[,count])=>sum+Number(count),0);return {registers,logic:total-registers};}
function renderSynthesis(report,prompt=report.prompt){state.synthesis=report;state.synthesisPrompt=prompt;$('export-synthesis').disabled=false;$('export-netlist').disabled=!report.netlist_verilog;$('export-script').disabled=!report.synthesis_script;$('synthesis-status').textContent=report.correct?'Generic netlist generated · oracle verified':'Generic netlist generated · verification not accepted';const counts=report.cell_counts||report.resources?.cell_types||{};const breakdown=genericCellBreakdown(counts);$('synthesis-result').className='result-filled';$('synthesis-result').innerHTML=`<p id="stale-synthesis" class="notice" hidden>This synthesis report uses an earlier ${isGenerated(report)?'specification or workload prompt':'specification'}. Synthesize the current configuration to refresh it.</p><div class="result-top"><div><h3>Generic logic, with a receipt.</h3><p>${report.spec.size} × ${report.spec.size} INT8 · ${report.lanes} lane${report.lanes>1?'s':''} · Custom ASIC</p></div><span class="tag">GENERIC SYNTHESIS · NOT A PHYSICAL CHIP</span></div>${isGenerated(report)?'<p class="evidence-origin">Source: AI-generated RTL, verified by simulation against an integer oracle. This separate generic synthesis report includes netlist verification.</p>':''}<div class="metrics"><div class="metric"><small>GENERIC CELLS</small><strong>${Number(report.cell_count??report.resources?.generic_cells).toLocaleString()}</strong></div><div class="metric"><small>REGISTER CELLS</small><strong>${breakdown.registers.toLocaleString()}</strong></div><div class="metric"><small>OTHER LOGIC CELLS</small><strong>${breakdown.logic.toLocaleString()}</strong></div></div><p class="subtle">${report.correct?'Netlist simulation matched the integer reference.':'Netlist correctness is not verified.'} Register and other logic counts come from the same technology-independent Yosys netlist. They are not standard-cell area or power. This app report stops at generic synthesis. Separate SKY130 mapping and routed physical-design experiments are recorded in the repository; unresolved electrical and antenna checks prevent signoff.</p><details><summary>Inspect generic cell types</summary><table class="cell-table"><thead><tr><th scope="col">Cell type</th><th scope="col">Count</th></tr></thead><tbody>${Object.entries(counts).map(([type,count])=>`<tr><td>${escapeHtml(type)}</td><td>${escapeHtml(count)}</td></tr>`).join('')}</tbody></table></details><details><summary>Inspect synthesis provenance, netlist, and limitations</summary><ul>${(report.limitations||[]).map(t=>`<li>${escapeHtml(t)}</li>`).join('')}</ul><pre>${escapeHtml(JSON.stringify(report,null,2))}</pre></details>`;updateEvidenceState();}
async function synthesize(lanes){if(state.busy||!$('spec-form').reportValidity())return;const spec=readSpec();if(spec.target!=='asic'||lanes>spec.max_lanes)return;setBusy(true);await explore();notice(`Running actual Yosys synthesis for ${lanes} lane${lanes>1?'s':''}, then verifying the generated netlist…`);try{const report=await api('/api/asic/synthesize',{spec,lanes});if(report.evidence!=='generic_synthesis'||report.correct!==true)throw new Error('Generic synthesis did not return an oracle-verified netlist report.');renderSynthesis(report);await history();notice('Generic synthesis complete. Physical area, power, and achieved timing remain unknown.');$('asic-stage').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}catch(e){notice(e.message,true);}finally{setBusy(false);await explore();}}
$('export-synthesis').onclick=()=>{if(state.synthesis)downloadReport(state.synthesis,`siliconos-asic-${state.synthesis.id||'synthesis'}.json`);};

function downloadSynthesisText(field,extension){const report=state.synthesis;if(!report?.[field])return;const url=URL.createObjectURL(new Blob([report[field]],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`siliconos-asic-${report.spec.size}x${report.spec.size}-${report.lanes}lane.${extension}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export-netlist').onclick=()=>downloadSynthesisText('netlist_verilog','v');
$('export-script').onclick=()=>downloadSynthesisText('synthesis_script','ys');

$('share-feedback').onclick=()=>{$('pilot').querySelector('details').open=true;};

$('import-vivado').onclick=async()=>{if(state.busy)return;const reportFile=$('vivado-report-file').files?.[0],metadataFile=$('vivado-metadata-file').files?.[0];if(!reportFile||!metadataFile){$('vivado-import-status').textContent='Choose both Vivado files first.';return;}try{setBusy(true);const [report,metadata]=await Promise.all([reportFile.text(),metadataFile.text()]);const parsed=await api('/api/vivado/utilization',{report,metadata});state.vivadoImports[`${parsed.parameters.N}:${parsed.parameters.LANES}`]=parsed;$('vivado-import-status').textContent=`Imported ${parsed.parameters.N}×${parsed.parameters.N}, ${parsed.parameters.LANES} lanes: ${parsed.resources.dsp} DSPs reported by Vivado ${parsed.vivado_version}. ${parsed.scope||'Out-of-context kernel'}; source binding ${parsed.source_binding_verified?'matches this checkout':'unverified'}. Board execution remains separate.`;await explore();}catch(e){$('vivado-import-status').textContent='Import rejected: '+e.message;}finally{setBusy(false);}};

// The graph is deterministic. Groq may explain this reviewed graph, but never supplies topology or evidence.
function architectureMapKey(spec){return JSON.stringify(spec,Object.keys(spec).sort());}
function architectureMapHtml(){const recipe=state.architecturePlan,spec=recipe.spec,lanes=recipe.parameters.LANES,target=spec.target==='kv260'?'KV260 programmable logic':'generic ASIC exploration',explanation=state.architectureExplanation?.key===architectureMapKey(spec)?state.architectureExplanation.value:null,laneBlocks=Array.from({length:lanes},(_,index)=>`<span class="architecture-lane">MAC ${index+1}</span>`).join('');return `<article class="architecture-map-card"><div class="architecture-map-head"><div><span class="eyebrow">VALIDATED CATALOG PLAN · ${escapeHtml(recipe.block_id)}</span><h3>${spec.size} × ${spec.size} signed INT8 matrix multiply</h3></div><span class="tag">CONCEPTUAL · NOT VIVADO</span></div><div class="architecture-flow" role="img" aria-label="Conceptual flow from reviewed configuration through ${lanes} MAC lanes to ${target}"><div class="architecture-node intent"><small>REVIEWED INPUT</small><strong>Requirement &amp; constraints</strong><span>${spec.objective==='minimize_latency'?'Prefer lower modeled compute cycles':'Prefer fewer arithmetic lanes'}</span></div><span class="architecture-arrow">→</span><div class="architecture-node config"><small>VALIDATED CONFIG</small><strong>N=${spec.size} · INT8 → INT32</strong><span>${lanes} selected lane${lanes>1?'s':''} · ${spec.frequency_mhz} MHz requested</span></div><span class="architecture-arrow">→</span><div class="architecture-node compute"><small>CATALOG RTL SHAPE</small><strong>${lanes===1?'Sequential compute lane':'Parallel compute lanes'}</strong><div class="architecture-lanes">${laneBlocks}</div></div><span class="architecture-arrow">→</span><div class="architecture-node integration"><small>CONCEPTUAL TARGET</small><strong>${target}</strong><span>${spec.target==='kv260'?'AXI-Lite wrapper exists separately; board integration pending':'RTL → generic synthesis path only'}</span></div></div><div class="architecture-map-foot"><p>${explanation?escapeHtml(explanation.summary):'This diagram follows the validated catalog recipe. Planning is not simulation, synthesis, timing closure, or board evidence.'}</p><button data-architecture-map class="button outline" ${state.busy||!state.ai?'disabled':''}>${explanation?'Refresh AI explanation':'Ask AI to explain this map'} ↗</button></div>${explanation?`<div class="architecture-ai-copy"><strong>${escapeHtml(explanation.title)}</strong><p>${escapeHtml(explanation.selection_reason)}</p><ul>${explanation.assumptions.map(item=>`<li>${escapeHtml(item)}</li>`).join('')}</ul><small>AI explanatory copy · configuration and graph remain deterministic · not implementation evidence</small></div>`:''}</article>`;}
const architectureMapContainer=$('architecture-map-container');
function schematicHtml(plan){const lanes=plan.parameters.LANES,n=plan.parameters.N,laneCards=Array.from({length:lanes},(_,i)=>`<div class="schematic-lane"><span>LANE ${i+1}</span><strong>8 × 8 → 16</strong><small>signed multiply</small><b>＋</b><strong>32-bit acc</strong></div>`).join('');return `<div class="schematic" role="img" aria-label="RTL data path: signed INT8 A and B operand arrays feed ${lanes} multiplier and INT32 accumulator lanes; results go to the C output array. Row, column, and k counters sequence the lanes."><div class="schematic-title"><span>RTL DATA PATH / ${n} × ${n}</span><span>${lanes} LANE${lanes>1?'S':''} · ${plan.block_id.split('.').at(-1).toUpperCase()}</span></div><div class="schematic-grid"><div class="schematic-inputs"><div class="schematic-block"><small>OPERAND A</small><strong>INT8 array</strong><span>${n} × ${n} signed values</span></div><div class="schematic-block"><small>OPERAND B</small><strong>INT8 array</strong><span>${n} × ${n} signed values</span></div></div><div class="schematic-wire"><span>A[row, k]<br>B[k, col + lane]</span></div><div class="schematic-compute"><small>PARALLEL COMPUTE · ${lanes} ×</small><div class="schematic-lanes">${laneCards}</div></div><div class="schematic-wire"><span>INT32 results</span></div><div class="schematic-block schematic-output"><small>OUTPUT C</small><strong>INT32 array</strong><span>${n} × ${n} results</span></div></div><div class="schematic-control"><span>CONTROL PATH</span><strong>row · col · k counters</strong><span>start → busy → done</span><span>One reduction step per active cycle; output written at k = N − 1</span></div><p class="schematic-caption">Source shape: checked-in <code>hardware/matmul.sv</code>. Arrays are RTL storage, not a BRAM mapping claim. Host loading and board integration are outside this compute path.</p></div>`;}
function renderArchitectureMap(){const container=architectureMapContainer,plan=state.architecturePlan;if(!plan||!sameObject(plan.spec,readSpec())){container.hidden=true;container.innerHTML='';return;}container.hidden=false;container.innerHTML=architectureMapHtml()+schematicHtml(plan);const button=container.querySelector('[data-architecture-map]');if(button)button.onclick=generateArchitectureMap;}
for(const key of ['size','precision','frequency_mhz','max_dsps','max_lanes','objective']){const control=$(key),previous=control.oninput;control.oninput=event=>{if(previous)previous(event);renderArchitectureMap();if(state.architecturePlan&&!sameObject(state.architecturePlan.spec,readSpec()))$('block-diagram-status').textContent='Selection changed. Develop the block diagram again for this configuration.';};}
async function developBlockDiagram(){if(state.busy||!$('spec-form').reportValidity())return;const spec=readSpec(),button=$('develop-block-diagram');button.disabled=true;$('block-diagram-status').textContent='Validating selected catalog recipe…';try{const plan=await api('/api/plan',{spec});if(plan.evidence!=='build_plan'||!plan.parameters||!sameObject(plan.spec,spec))throw new Error('Server did not return a matching validated plan.');state.architecturePlan=plan;renderArchitectureMap();$('block-diagram-status').textContent=`Diagram developed from ${plan.block_id}. Conceptual plan only; no implementation result implied.`;}catch(error){state.architecturePlan=null;renderArchitectureMap();$('block-diagram-status').textContent='Block diagram unavailable: '+error.message;}finally{button.disabled=false;}}
$('develop-block-diagram').onclick=developBlockDiagram;
async function generateArchitectureMap(){if(state.busy||!state.ai||!state.architecturePlan)return;try{setBusy(true);notice('Generating a constrained plain-language explanation for the reviewed architecture map…');const spec=state.architecturePlan.spec,value=await api('/api/architecture-map',{spec});state.architectureExplanation={key:architectureMapKey(spec),value};renderArchitectureMap();notice('AI architecture explanation ready. The graph remains derived from reviewed configuration, not Vivado implementation data.');}catch(error){notice('AI architecture explanation rejected: '+error.message,true);}finally{setBusy(false);renderArchitectureMap();}}
const exploreBeforeArchitectureMap=explore;
explore=async function(...args){renderArchitectureMap();const result=await exploreBeforeArchitectureMap(...args);renderArchitectureMap();if(state.architecturePlan&&!sameObject(state.architecturePlan.spec,readSpec()))$('block-diagram-status').textContent='Selection changed. Develop the block diagram again for this configuration.';return result;};

// Demo path: Groq explains a reviewed architecture; deterministic catalog code is what runs.
const updateGenerateRtlBeforeCatalogAssembly=updateGenerateRtl;
updateGenerateRtl=function(){const spec=readSpec(),lanes=spec.objective==='minimize_lanes'?1:spec.max_lanes,missing=[];if(!state.simulator)missing.push('Icarus Verilog');if(spec.target==='asic'&&!state.asicSynthesis)missing.push('Yosys synthesis');const button=$('generate-rtl');button.disabled=state.busy||missing.length>0;button.innerHTML='Assemble &amp; verify catalog RTL <span>↗</span>';button.title=missing.length?'Requires '+missing.join(', '):'Deterministically selects qualified catalog RTL; Groq does not invent the datapath.';$('generate-rtl-help').textContent=`Selects the qualified ${lanes}-lane catalog recipe for your reviewed ${spec.size} × ${spec.size} specification, then runs the real RTL simulation and integer oracle.${spec.target==='asic'?' It also performs generic synthesis and netlist verification.':''}${missing.length?' Requires '+missing.join(', ')+'.':''}`;};
async function assembleCatalogRtl(){updateGenerateRtl();if($('generate-rtl').disabled||!$('spec-form').reportValidity())return;const spec=readSpec(),lanes=spec.objective==='minimize_lanes'?1:spec.max_lanes,button=$('generate-rtl');let accepted=false;setBusy(true);button.textContent=spec.target==='asic'?'Assembling, verifying & synthesizing…':'Assembling & verifying catalog RTL…';notice(spec.target==='asic'?'Selecting qualified catalog RTL, simulating it against the integer oracle, then synthesizing and verifying the netlist…':'Selecting qualified catalog RTL, then running it against the integer oracle…');try{const result=await api('/api/build',{spec,lanes});if(result.evidence!=='rtl_simulation'||result.correct!==true||(spec.target==='asic'&&(result.synthesis?.evidence!=='generic_synthesis'||result.synthesis?.correct!==true)))throw new Error('The server did not return a fully verified catalog build. No report displayed.');state.runs=[result,...state.runs];renderResult(result);if(result.synthesis)renderSynthesis(result.synthesis);accepted=true;await history();notice('Qualified catalog RTL assembled and verified against the integer oracle.'+(result.synthesis?' Generic synthesis and netlist verification also passed.':'')+' Groq did not generate the datapath.');$('evidence').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}catch(error){notice(accepted?'Catalog verification passed. The accepted report remains displayed, but history could not be refreshed: '+error.message:'Catalog RTL assembly rejected: '+error.message+((state.result||state.synthesis)?' The previously verified report remains displayed.':''),true);}finally{setBusy(false);updateGenerateRtl();await explore();}}
generateRtl=assembleCatalogRtl;
$('generate-rtl').onclick=generateRtl;
updateGenerateRtl();

// Keep every user-facing label tied to the reviewed numerical contract.
function syncPrecisionCopy(){
  const precision=readSpec().precision.toUpperCase();
  $('spec-target').textContent=`Signed ${precision} → INT32 · ${targetLabel(state.spec.target)}`;
  $('prompt').placeholder=`Describe a signed ${precision} matrix multiplication accelerator for ${targetLabel(state.spec.target)}.`;
}
const fillSpecWithPrecision=fillSpec;
fillSpec=function(...args){const result=fillSpecWithPrecision(...args);syncPrecisionCopy();return result;};
const precisionControl=$('precision'),previousPrecisionInput=precisionControl.oninput;
precisionControl.oninput=event=>{if(previousPrecisionInput)previousPrecisionInput(event);state.spec=readSpec();syncPrecisionCopy();};
const renderResultWithPrecision=renderResult;
renderResult=function(report){renderResultWithPrecision(report);$('result').innerHTML=$('result').innerHTML.replaceAll('INT8',report.spec.precision.toUpperCase());};
const renderSynthesisWithPrecision=renderSynthesis;
renderSynthesis=function(report,...args){renderSynthesisWithPrecision(report,...args);$('synthesis-result').innerHTML=$('synthesis-result').innerHTML.replaceAll('INT8',report.spec.precision.toUpperCase());};
syncPrecisionCopy();

function updateVivadoImportControl(){
  const ready=Boolean($('vivado-report-file').files?.length&&$('vivado-metadata-file').files?.length);
  $('import-vivado').disabled=state.busy||!ready;
  if(ready&&$('vivado-import-status').textContent==='No Vivado report imported.')
    $('vivado-import-status').textContent='Files selected. Import the matching report and manifest.';
}
for(const id of ['vivado-report-file','vivado-metadata-file']){
  $(id).onchange=updateVivadoImportControl;
}
updateVivadoImportControl();
